// ===========================================================================
//  CẤU HÌNH
// ===========================================================================
const WATCHLIST = ['VNM', 'FPT', 'HPG', 'MWG', 'VCB', 'SSI', 'DGC', 'VND', 'MBB', 'STB'];

// gn(q)=báo VN (tiếng Việt); gn(q,true)=báo QUỐC TẾ (tiếng Anh, độc lập hơn về vĩ mô)
const gn = (q, en) => 'https://news.google.com/rss/search?q=' + encodeURIComponent(q) + (en ? '&hl=en&gl=US&ceid=US:en' : '&hl=vi&gl=VN&ceid=VN:vi');

const FEEDS = [
  { name: 'VN - Thị trường CK', vn: true, url: gn('chứng khoán OR "VN-Index" when:1d') },
  { name: 'VN - Doanh nghiệp',  vn: true, url: gn('cổ phiếu doanh nghiệp niêm yết when:1d') },
  { name: 'VN - Watchlist',     vn: true, url: gn('(' + WATCHLIST.map(t => '"' + t + '"').join(' OR ') + ') cổ phiếu when:2d') },
  { name: 'VN - Vĩ mô',         vn: true, url: gn('lãi suất OR tỷ giá OR "Ngân hàng Nhà nước" when:1d') },
  // Báo quốc tế - lớp vĩ mô độc lập (Reuters/Bloomberg/Nikkei...)
  { name: 'QUỐC TẾ - VN macro', vn: false, url: gn('Vietnam stock market OR "State Bank of Vietnam" OR "Vietnam economy" when:3d', true) },
  { name: 'QUỐC TẾ - dòng vốn/nâng hạng', vn: false, url: gn('Vietnam "FTSE" OR "MSCI" OR "emerging market" OR "foreign investors" OR exports when:5d', true) },
];
const MAX_PER_FEED = 8;
const MAX_AGE_HOURS = 30;
// ===========================================================================

const headers = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
  'Accept': 'application/rss+xml, application/xml, text/xml, */*',
};
const cutoff = Date.now() - MAX_AGE_HOURS * 3600 * 1000;

const pick = (xml, tag) => {
  const m = xml.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i'));
  if (!m) return '';
  return m[1].replace(/<!\[CDATA\[/g, '').replace(/\]\]>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ').trim();
};

const vnNews = [], intlNews = [];
const debug = [];
const seen = new Set();
for (const f of FEEDS) {
  try {
    const body = await this.helpers.httpRequest({ method: 'GET', url: f.url, headers, json: false, timeout: 20000 });
    const xml = typeof body === 'string' ? body : String(body);
    const blocks = (xml.match(/<item[\s\S]*?<\/item>/gi) || []).slice(0, MAX_PER_FEED);
    let count = 0;
    for (const it of blocks) {
      const title = pick(it, 'title');
      const src = pick(it, 'source');
      const key = title.toLowerCase().slice(0, 70);
      if (title && !seen.has(key)) {
        seen.add(key);
        (f.vn ? vnNews : intlNews).push('[' + (src || f.name) + '] ' + title);
        count++;
      }
    }
    debug.push(f.name + ': ' + count + ' tin');
  } catch (e) {
    debug.push(f.name + ': ❌ ' + (e.message || String(e)));
  }
}

// Dòng tiền khối ngoại (dữ liệu CỨNG để đối chiếu tin)
const flowLines = [];
for (const t of WATCHLIST) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + t + '&size=5&sort=tradingDate:desc',
      headers: { 'User-Agent': headers['User-Agent'], 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' },
      json: true, timeout: 15000,
    });
    const ses = (res && res.data) || [];
    if (!ses.length) continue;
    const nets = ses.map(s => (s.netVal || 0) / 1e9);
    flowLines.push(t + ': 5 phiên [' + nets.map(v => v.toFixed(1)).join(', ') + '] tỷ, tổng ' + nets.reduce((a, b) => a + b, 0).toFixed(1) + ' tỷ');
  } catch (e) { /* skip */ }
}
debug.push('Khối ngoại: ' + flowLines.length + '/' + WATCHLIST.length + ' mã');

const vnText   = vnNews.length ? vnNews.map((x, i) => (i + 1) + '. ' + x).join('\n') : '(không lấy được tin VN)';
const intlText = intlNews.length ? intlNews.map((x, i) => (i + 1) + '. ' + x).join('\n') : '(không lấy được tin quốc tế)';
const flowText = flowLines.length ? flowLines.join('\n') : '(không lấy được dòng tiền)';

const today = new Date().toLocaleDateString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', weekday: 'long', day: 'numeric', month: 'numeric', year: 'numeric' });

const system = 'Bạn là chuyên viên phân tích chứng khoán VN cho một nhà đầu tư cá nhân. Viết BÁO CÁO SÁNG ngắn gọn, tỉnh táo, bằng tiếng Việt.\n\n'
  + 'BA NGUỒN, ĐỘ TIN CẬY KHÁC NHAU — phải ĐỐI CHIẾU CHÉO:\n'
  + '1) TIÊU ĐỀ BÁO VN: chỉ là TIÊU ĐỀ, dễ GIẬT TÍT/câu view → coi mỗi tiêu đề là TUYÊN BỐ CHƯA KIỂM CHỨNG, KHÔNG phải sự thật. Ưu tiên tin có SỐ LIỆU cụ thể; bỏ qua tiêu đề mơ hồ/cảm tính.\n'
  + '2) BÁO QUỐC TẾ: độc lập hơn với áp lực trong nước, MẠNH về VĨ MÔ (Fed, USD, dòng vốn ngoại, nâng hạng FTSE/MSCI). Dùng cho BỐI CẢNH; lưu ý báo ngoại hầu như KHÔNG đưa tin mã nhỏ cụ thể.\n'
  + '3) DỮ LIỆU CỨNG (dòng tiền khối ngoại): đây là HÀNH ĐỘNG bằng tiền thật → tin cậy NHẤT. Dùng nó làm QUAN TOÀ.\n\n'
  + 'Nguyên tắc bắt buộc:\n'
  + '- Một tin chỉ đáng tin khi có ≥2 nguồn xác nhận HOẶC dữ liệu cứng ủng hộ. Tin tốt mà khối ngoại xả (hoặc ngược lại) = MÂU THUẪN, nêu bật và NGHIÊNG VỀ DỮ LIỆU.\n'
  + '- Nêu rõ chỗ báo VN và báo quốc tế NÓI KHÁC NHAU về cùng một vấn đề (nếu có) — đó là tín hiệu đáng chú ý.\n'
  + '- GẮN CỜ tin nghi giật tít: tiêu đề kêu to nhưng không có số liệu và không nguồn nào khác/dữ liệu nào xác nhận.\n'
  + '- Ưu tiên watchlist: ' + WATCHLIST.join(', ') + '. KHÔNG khuyến nghị mua/bán. KHÔNG bịa số.\n'
  + '- Bố cục: (1) 🔥 Điểm tin ĐÃ KIỂM CHỨNG tác động watchlist, (2) 🌐 Bối cảnh vĩ mô (ưu tiên góc nhìn báo quốc tế), (3) ⚠️ Mâu thuẫn / tin nghi giật tít / rủi ro.\n'
  + '- Ngắn gọn, dễ đọc điện thoại, Markdown đơn giản, tối đa ~600 từ.';

const userContent = 'Hôm nay ' + today + '.\n\n'
  + '=== TIÊU ĐỀ BÁO VN (chưa kiểm chứng, dễ giật tít) ===\n' + vnText
  + '\n\n=== TIÊU ĐỀ BÁO QUỐC TẾ (độc lập, vĩ mô) ===\n' + intlText
  + '\n\n=== DỮ LIỆU CỨNG - DÒNG TIỀN KHỐI NGOẠI (tỷ đồng, + là mua ròng) ===\n' + flowText
  + '\n\nViết báo cáo sáng theo bố cục yêu cầu, ĐỐI CHIẾU CHÉO 3 nguồn, lấy dữ liệu cứng làm quan toà.';

const requestBody = { model: 'claude-opus-4-8', max_tokens: 4000, system, messages: [{ role: 'user', content: userContent }] };

return [{ json: { requestBody, vn: vnNews.length, intl: intlNews.length, debug } }];

const res = $input.first().json;
let text = '';
if (res && Array.isArray(res.content)) text = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
if (!text) {
  if (res && res.type === 'error' && res.error) text = '⚠️ Lỗi API: ' + (res.error.message || JSON.stringify(res.error));
  else if (res && res.stop_reason === 'refusal') text = '⚠️ Bị từ chối bởi bộ lọc an toàn.';
  else text = '⚠️ Không tạo được báo cáo (phản hồi rỗng).';
}
const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
const full = '☀️ *BÁO CÁO SÁNG THỊ TRƯỜNG*\n_' + now + '_\n\n' + text + '\n\n_Nguồn: báo VN + báo quốc tế + dòng tiền khối ngoại · đối chiếu chéo bởi Claude AI · KHÔNG phải khuyến nghị đầu tư_';
const SIZE = 3800;
const parts = [];
let s = full;
while (s.length > SIZE) { let cut = s.lastIndexOf('\n', SIZE); if (cut < SIZE * 0.5) cut = SIZE; parts.push(s.slice(0, cut)); s = s.slice(cut); }
if (s.trim()) parts.push(s);
return parts.map(p => ({ json: { message: p } }));
